import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {acceptedAnalysis,analysisPath,dateRangeIndex,holdingRows,metricCsv,metricDefinitions,metricText,rangeStart,resultMetrics,tradeRows} from '../src/results/model.ts';

// Synthetic contract fixtures generated by AQ tests/analysis/fixtures.py. Not real backtests.
const cases=JSON.parse(readFileSync(new URL('./fixtures/result-analysis.json',import.meta.url)));
const clone=value=>structuredClone(value);
const accept=f=>acceptedAnalysis(f.analysis,f.job.job_id,f.job.result.snapshot_sha256);

test('the twenty design items keep their original order and use one backend payload',()=>{
  const fixture=cases[0],a=accept(fixture);assert.ok(a);assert.equal(metricDefinitions.length,20);
  assert.deepEqual(metricDefinitions.slice(0,4).map(x=>x[1]),['策略收益','策略年化收益','超额收益','基准收益']);
  const metrics=resultMetrics(fixture.result.summary,a),csv=metricCsv(fixture.result.summary,a);
  assert.equal(csv.length,21);
  metricDefinitions.forEach(([key,label],i)=>{assert.equal(csv[i+1][0],label);assert.equal(csv[i+1][1],metrics[key].value);});
});

test('wrong run, wrong frozen hash, unsupported versions and non-finite values are rejected',()=>{
  const fixture=cases[0];
  for(const change of [a=>a.job_id='another',a=>a.source_sha256='a'.repeat(64),a=>a.schema_version='other',
    a=>a.calculation_version='unreviewed',a=>a.metrics.sharpe.value=Infinity,
    a=>a.series[0].return=NaN,a=>a.series[0].date='2025-02-30',a=>a.series.reverse(),
    a=>a.metrics.sharpe.status='unavailable',a=>a.sample_count++]){
    const copy=clone(fixture);change(copy.analysis);assert.equal(accept(copy),null);
  }
});

test('missing benchmark and short samples remain null with readable reasons, not zero',()=>{
  const missing=accept(cases[1]),short=accept(cases[2]);assert.ok(missing);assert.ok(short);
  assert.equal(missing.metrics.benchmark_return.value,null);
  assert.equal(missing.metrics.benchmark_return.reason,'missing_benchmark');
  assert.equal(metricText(missing.metrics.benchmark_return),'—');
  assert.equal(short.metrics.sharpe.reason,'insufficient_samples');
  assert.equal(short.metrics.win_rate.reason,'no_closed_trades');
  assert.equal(metricText({value:0,unit:'percent'}),'0.00%');
  const fallback=resultMetrics({net_return:0,max_drawdown:0,sharpe:NaN},null);
  assert.equal(fallback.net_return.value,0);assert.equal(fallback.sharpe.value,null);
  assert.equal(fallback.sharpe.reason,'missing_analysis');
});

test('analysis is read from the same result family and never requests a factor analysis or submit route',()=>{
  const r=cases[0].result;
  assert.equal(analysisPath('/history/jobs/abc',r,null,'python'),'/history/jobs/abc/analysis');
  assert.equal(analysisPath('/python/jobs/abc',r,null,'python'),'/python/jobs/abc/analysis');
  assert.equal(analysisPath('/python/jobs/abc',r,accept(cases[0]),'python'),null);
  assert.equal(analysisPath('/factors/jobs/abc',r,null,'factors'),null);
  assert.equal(analysisPath('/python/jobs/abc',null,null,'python'),null);
});

test('trades join by order/fill identity and missing fees/type/PnL are not fabricated',()=>{
  const fixture=cases[0],analysis=accept(fixture),rows=tradeRows(fixture.result.native,analysis);
  assert.equal(rows[0].order_time,'09:59:00');assert.equal(rows[0].order_type,'市价单');
  assert.equal(rows[0].pnl,'—');assert.equal(rows[1].side,'卖');assert.notEqual(rows[1].pnl,'—');
  assert.equal(rows[1].fees,'13.64');
  const native=clone(fixture.result.native);delete native.orders[0].order_type;delete native.trades[0].tax;
  const unknown=tradeRows(native,null);assert.equal(unknown[0].order_type,'—');
  assert.equal(unknown[0].fees,'—');assert.equal(unknown[1].pnl,'—');
});

test('daily holdings include actual cash without invented cash PnL',()=>{
  const fixture=cases[0],analysis=accept(fixture),rows=holdingRows(fixture.result.native,analysis);
  const cash=rows.filter(r=>r.security.startsWith('现金'));
  assert.equal(cash.length,fixture.result.native.accounts.length);
  assert.equal(cash[0].value,'79,995.00');assert.equal(cash[0].pnl,'—');
  assert.notEqual(rows[0].pnl,'—');
  assert.equal(holdingRows(fixture.result.native,null)[0].pnl,'—');
});

test('month range clamps month ends and preserves the initial-capital anchor for all dates',()=>{
  const points=['2025-01-31','2025-02-27','2025-02-28','2025-03-03','2025-03-31'].map(date=>({date}));
  assert.equal(rangeStart(points,1),3);assert.equal(rangeStart(points,12),0);
  assert.equal(rangeStart([],1),0);
});

test('an end date on a non-session selects the previous session, not a future one',()=>{
  const points=['2025-02-28','2025-03-03','2025-03-04'].map(date=>({date}));
  assert.equal(dateRangeIndex(points,'2025-03-02',true),1);
  assert.equal(dateRangeIndex(points,'2025-03-02',false),2);
  assert.equal(dateRangeIndex(points,'2025-02-28',false),0);
  assert.equal(dateRangeIndex(points,'2025-02-30',true),null);
});

test('new styling is scoped to the results page rather than changing other pages',()=>{
  const css=readFileSync(new URL('../src/results/results.css',import.meta.url),'utf8');
  for(const line of css.split('\n').filter(Boolean))assert.ok(line.startsWith('.result-analysis ')||line.startsWith('@media('));
});
